INSERT INTO public.missions (id, title, description, compatible_modes, category, difficulty, base_points, estimated_duration_minutes, target_participants, verification_type, special_conditions, is_secret) VALUES
('bar_01', 'L''Ordine Speculare', 'Fai ordinare a un altro partecipante lo stesso identico drink o consumazione che hai ordinato tu, senza mai nominarlo direttamente prima che ordini.', ARRAY['bar','house_party'], 'persuasione', 'media', 150, 15, 2, 'peer_target', ARRAY['Non puoi offrire tu la consumazione.'], true),
('bar_02', 'L''Esperto Sommelier Fittizio', 'Inventati un difetto o una nota aromatica completamente assurda del tuo bicchiere (es. "retrogusto di quercia affumicata da temporale estivo") e convinci qualcuno al tavolo a fingere di sentirla.', ARRAY['bar','house_party'], 'bluff', 'facile', 90, 10, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_03', 'Il Critico del Sottobicchiere', 'Costruisci o posiziona una torre di almeno 4 sottobicchieri o tappi di fronte a un compagno di gioco senza che te la abbatta per almeno 5 minuti.', ARRAY['bar'], 'creativita', 'facile', 80, 8, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_04', 'Niente Parole Proibite: Drink & Bar', 'Parla per 10 minuti continui senza mai pronunciare le parole "bere", "drink", "bicchiere", "cocktail" o "bar", facendoti comunque capire quando ordinate o parlate.', ARRAY['bar','house_party'], 'bluff', 'media', 140, 10, 1, 'peer_witness', ARRAY[]::text[], true),
('bar_05', 'Lo Sguardo dell''Alibi', 'Scopri quale drink ha ordinato un altro giocatore prima di lui guardando solo cosa prepara il bartender, e sussurraglielo all''orecchio prima che il bicchiere tocchi il tavolo.', ARRAY['bar'], 'osservazione', 'difficile', 220, 12, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_06', 'Il Falso Ricordo d''Infanzia', 'Racconta al tavolo una storia totalmente inventata sul tuo primo lavoro estivo assurdo e fai annuire convinto almeno un altro giocatore dicendo "Sì, me lo avevi già raccontato!".', ARRAY['bar','house_party'], 'bluff', 'difficile', 250, 15, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_07', 'Brindisi con Movente', 'Avvia un brindisi corale solenne al tavolo dedicandolo a una causa fittizia, bizzarra ma apparentemente nobile (es. "Ai lampioni a risparmio energetico").', ARRAY['bar','house_party'], 'socializzazione', 'facile', 90, 5, 3, 'group_vote', ARRAY[]::text[], true),
('bar_08', 'La Parola Infiltrata: "Pappagallo"', 'Inserisci la parola "pappagallo" (o suo derivato) in 3 conversazioni separate con 3 persone diverse nell''arco di 15 minuti, senza destare sospetti.', ARRAY['bar','house_party','outdoor'], 'persuasione', 'media', 160, 15, 3, 'peer_witness', ARRAY[]::text[], true),
('bar_09', 'L''Intervista Clandestina', 'Fai confessare a un altro partecipante il suo peggior acquisto compulsivo degli ultimi 6 mesi, senza fargli capire che sei in missione.', ARRAY['bar','house_party','outdoor'], 'deduzione', 'media', 150, 10, 2, 'peer_target', ARRAY[]::text[], true),
('bar_10', 'Il Tocco delle Mani Incrociate', 'Fai in modo che due altri giocatori del gruppo si scambino involontariamente un oggetto (accendino, tovagliolo, cellulare, chiavi) passando attraverso di te.', ARRAY['bar','house_party'], 'persuasione', 'difficile', 210, 12, 3, 'peer_witness', ARRAY[]::text[], true),
('bar_11', 'Scommessa a Orologio', 'Indovina l''orario esatto della prossima volta che qualcuno del gruppo si alza per andare in bagno o al bancone con un margine di errore inferiore a 3 minuti.', ARRAY['bar','house_party'], 'osservazione', 'media', 170, 20, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_12', 'L''Accento Camaleonte', 'Sostieni una conversazione di almeno 3 minuti adottando una cadenza regionale o straniera impercettibilmente alterata senza farti sbeffeggiare apertamente.', ARRAY['bar','house_party'], 'creativita', 'difficile', 230, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_13', 'Patto del Bancone (Coop)', 'Collabora con il tuo partner per far ordinare a un terzo giocatore una ciotola di patatine o arachidi extra senza che capisca che stavate complottando.', ARRAY['bar'], 'collaborazione', 'media', 180, 15, 3, 'peer_target', ARRAY[]::text[], true),
('bar_14', 'La Teoria del Complotto Quotidiano', 'Convincere due compagni che un oggetto comunissimo del locale (es. la forma delle cannucce o il logo sui bicchieri) ha un significato psicologico nascosto.', ARRAY['bar','house_party'], 'bluff', 'difficile', 240, 15, 3, 'peer_witness', ARRAY[]::text[], true),
('bar_15', 'Sincronia di Bicchieri', 'Fai in modo che tu e un altro giocatore ignaro appoggiate il bicchiere sul tavolo nello stesso identico secondo per tre volte consecutive.', ARRAY['bar'], 'osservazione', 'leggendaria', 380, 25, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_16', 'Il Soprannome Improvviso', 'Inizia a chiamare un partecipante con un soprannome insolito e fa in modo che un terzo membro del gruppo inizi a usarlo spontaneamente nella conversazione.', ARRAY['bar','house_party','outdoor'], 'persuasione', 'difficile', 260, 20, 3, 'peer_witness', ARRAY[]::text[], true),
('bar_17', 'Dilemma del Menù', 'Fai passare a un amico almeno 4 minuti a riflettere indeciso su quale bevanda o snack prendere, continuando a fargli domande retoriche.', ARRAY['bar'], 'persuasione', 'facile', 100, 6, 2, 'peer_target', ARRAY[]::text[], true),
('bar_18', 'Il Maestro del Ghiaccio', 'Sposta discretamente 3 cubetti di ghiaccio o cannucce usate da un bicchiere a un piattino senza che il proprietario del drink se ne accorga per 2 minuti.', ARRAY['bar'], 'chaos', 'media', 160, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('bar_19', 'Lo Sbadiglio a Catena', 'Sbadiglia vistosamente e fai sbadigliare per contagio almeno altri due partecipanti entro 90 secondi.', ARRAY['bar','house_party','outdoor'], 'osservazione', 'facile', 110, 3, 3, 'peer_witness', ARRAY[]::text[], true),
('bar_20', 'L''Opinione Controcorrente', 'Difendi con passione un film universalmente odiato o un cibo ripugnante finché un amico non ammette riluttante: "Beh, in fondo un punto ce l''hai".', ARRAY['bar','house_party','outdoor'], 'persuasione', 'media', 170, 10, 2, 'peer_target', ARRAY[]::text[], true),
('disco_01', 'La Mossa Specchio', 'Inventati un movimento di danza ritmico e ripetitivo sulla pista e convinci un compagno di gioco a imitarlo a specchio per almeno 15 secondi.', ARRAY['discoteca','house_party'], 'creativita', 'facile', 100, 5, 2, 'peer_target', ARRAY[]::text[], true),
('disco_02', 'Il Radar del Drop', 'Prevedi ad alta voce il momento esatto in cui la canzone "droppa" o cambia ritmo, alzando le braccia esattamente sul beat.', ARRAY['discoteca'], 'osservazione', 'facile', 80, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_03', 'La Comunicazione Morse a Bicchieri', 'Comunica una parola in codice di 4 lettere a un tuo amico attraverso la folla usando solo cenni del capo o gesti delle mani, senza usare la voce né il cellulare.', ARRAY['discoteca'], 'deduzione', 'difficile', 240, 8, 2, 'peer_target', ARRAY[]::text[], true),
('disco_04', 'Il Trenino Spontaneo', 'Innesca o partecipa a una fila di ballo o passo coordinato con almeno altri 3 compagni di gioco per almeno 30 secondi.', ARRAY['discoteca','house_party'], 'socializzazione', 'media', 150, 5, 4, 'group_vote', ARRAY[]::text[], true),
('disco_05', 'La Guardia del Corpo Improvvisata', 'Fai finta di essere la guardia del corpo seria e impassibile di un tuo amico mentre attraversa la pista da ballo per andare al bar.', ARRAY['discoteca'], 'creativita', 'facile', 110, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_06', 'L''Urlo sul Ritornello', 'Fai cantare a squarciagola il ritornello di una traccia a un amico che di solito non canta mai in pubblico.', ARRAY['discoteca','house_party'], 'persuasione', 'media', 160, 10, 2, 'peer_target', ARRAY[]::text[], true),
('disco_07', 'L''Ombra Fedele (Coop)', 'Con il tuo partner, posizionatevi contemporaneamente ai due lati di un terzo giocatore per 2 minuti ballando in sincronia perfetta senza che lui capisca il motivo.', ARRAY['discoteca'], 'collaborazione', 'media', 170, 6, 3, 'peer_witness', ARRAY[]::text[], true),
('disco_08', 'La Foto Mosse Perfetta', 'Scatta o fatti scattare una foto di gruppo mossa e sfocata che sembri la copertina di un album indie electro anni 2000.', ARRAY['discoteca','house_party'], 'creativita', 'facile', 90, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_09', 'La Scomparsa da Illusionista', 'Sparisci dalla vista di un tuo amico durante un momento di folla e ricompari esattamente alle sue spalle toccandogli la spalla opposta.', ARRAY['discoteca'], 'osservazione', 'media', 140, 10, 2, 'peer_target', ARRAY[]::text[], true),
('disco_10', 'Occhiali da Sole Notturni', 'Fai indossare a un compagno i tuoi occhiali da sole sulla pista da ballo buia per almeno una canzone intera senza lamentarsi.', ARRAY['discoteca','house_party'], 'persuasione', 'media', 150, 8, 2, 'peer_target', ARRAY[]::text[], true),
('disco_11', 'Indovina il DJ Set', 'Riconosci e scrivi in segreto sul telefono il genere o il campione della traccia successiva prima che entri la batteria principale, e mostralo come prova al compagno.', ARRAY['discoteca'], 'deduzione', 'difficile', 250, 15, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_12', 'Cerchio Hip-Hop da Salotto', 'Apri un cerchio di ballo tra voi amici e lancia dentro un compagno riluttante facendolo acclamare a gran voce da tutto il gruppo.', ARRAY['discoteca','house_party'], 'socializzazione', 'difficile', 230, 5, 4, 'group_vote', ARRAY[]::text[], true),
('disco_13', 'Il Labiale Sbagliato', 'Canta in playback con grande enfasi parole completamente diverse dal testo reale della canzone per 30 secondi finché qualcuno non ti guarda perplesso.', ARRAY['discoteca'], 'bluff', 'facile', 100, 3, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_14', 'La Finta Chiamata d''Emergenza', 'Mima l''ansia di una telefonata urgente nel frastuono della musica, chiedi silenzio con un dito a un amico e poi scoppia a ridere rivelando il nulla.', ARRAY['discoteca','bar'], 'bluff', 'media', 130, 5, 2, 'peer_target', ARRAY[]::text[], true),
('disco_15', 'La Trance Mistica', 'Rimani immobile come una statua in mezzo alla pista mentre tutti ballano intorno a te per 45 secondi di fila senza sorridere.', ARRAY['discoteca'], 'chaos', 'difficile', 270, 3, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_16', 'Il Battito di Mani Fuori Tempo', 'Inizia a battere le mani perfettamente in controtempo rispetto alla cassa e convincere almeno un altro amico a unirsi convinto al tuo ritmo storto.', ARRAY['discoteca'], 'persuasione', 'difficile', 260, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_17', 'Il Passaggio della Giacca', 'Riesci a far reggere la tua giacca, felpa o accessorio a un altro giocatore per più di 5 minuti senza che te lo chieda indietro subito.', ARRAY['discoteca','bar','house_party'], 'persuasione', 'media', 150, 10, 2, 'peer_target', ARRAY[]::text[], true),
('disco_18', 'High Five Volante', 'Scambia un batticinque a mezz''aria saltando contemporaneamente con un amico durante il drop di un brano.', ARRAY['discoteca'], 'socializzazione', 'facile', 90, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_19', 'Il Guardiano del Tavolo', 'Presidia il tavolo o il punto d''appoggio del gruppo per 10 minuti respingendo amichevolmente chiunque provi ad occuparlo.', ARRAY['discoteca','bar'], 'osservazione', 'media', 140, 12, 2, 'peer_witness', ARRAY[]::text[], true),
('disco_20', 'Il Re della Pista (Leggendaria)', 'Organizza una coreografia improvvisata con almeno 4 compagni di gioco che duri per un intero ritornello e termini con un pose-down finale.', ARRAY['discoteca'], 'collaborazione', 'leggendaria', 420, 15, 5, 'group_vote', ARRAY[]::text[], true),
('house_01', 'Il Custode del Frigorifero', 'Posizionati vicino al frigorifero o alla dispensa e commenta seriosamente ogni scelta di snack o bevanda presa da 3 amici diversi.', ARRAY['house_party'], 'socializzazione', 'facile', 90, 10, 3, 'peer_witness', ARRAY[]::text[], true),
('house_02', 'Il DJ Dirottatore', 'Riesci a far mettere in coda sulla cassa Bluetooth una canzone imbarazzante degli anni ''90 o 2000 senza che nessuno la skippi nei primi 90 secondi.', ARRAY['house_party','bar'], 'persuasione', 'media', 160, 10, 2, 'peer_witness', ARRAY[]::text[], true),
('house_03', 'L''Oggetto Infiltrato', 'Prendi un piccolo oggetto innocuo (un cucchiaino, una molletta, un tappo) e nascondilo nella tasca della giacca di un amico senza che se ne accorga.', ARRAY['house_party'], 'chaos', 'difficile', 230, 15, 2, 'peer_witness', ARRAY[]::text[], true),
('house_04', 'La Votazione Improvvisa', 'Lancia una votazione palese al volo su chi tra i presenti sopravviverebbe meno tempo in un''apocalisse zombie e fai votare almeno 4 persone.', ARRAY['house_party','bar','outdoor'], 'socializzazione', 'facile', 110, 5, 4, 'group_vote', ARRAY[]::text[], true),
('house_05', 'L''Ispezione Domestica', 'Trova l''oggetto più bizzarro o vintage esposto nella stanza e chiedi al padrone di casa l''aneddoto sulla sua origine.', ARRAY['house_party'], 'deduzione', 'facile', 100, 8, 2, 'peer_target', ARRAY[]::text[], true),
('house_06', 'La Battuta a Scoppio Ritardato', 'Racconta una freddura o un calambour pessimo e mantieni un''espressione totalmente seria finché qualcun altro non ride per l''imbarazzo.', ARRAY['house_party','bar','outdoor'], 'creativita', 'media', 130, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('house_07', 'Il Gioco del Silenzio Volontario', 'Non parlare per 7 minuti esatti durante la festa, comunicando solo a gesti o mimica, senza che nessuno pensi che tu sia arrabbiato.', ARRAY['house_party','bar'], 'bluff', 'difficile', 250, 8, 2, 'peer_witness', ARRAY[]::text[], true),
('house_08', 'Il Toast Perfetto', 'Prepara uno spuntino o assembla un piattino di stuzzichini per un amico decorandolo in modo ridicolmente artistico e formale.', ARRAY['house_party'], 'creativita', 'facile', 120, 8, 2, 'peer_target', ARRAY[]::text[], true),
('house_09', 'Lo Scambio di Sedie Inconsapevole', 'Fai cambiare sedia o divano a un amico senza chiedergli di alzarsi direttamente (es. chiedendogli di passarti qualcosa o indicando un dettaglio).', ARRAY['house_party'], 'persuasione', 'media', 170, 10, 2, 'peer_target', ARRAY[]::text[], true),
('house_10', 'Il Ritratto Segreto', 'Disegna su un foglietto o sul retro di un tovagliolo il ritratto caricaturale di un partecipante e faglielo trovare sotto il suo bicchiere.', ARRAY['house_party','bar'], 'creativita', 'media', 180, 10, 2, 'peer_target', ARRAY[]::text[], true),
('house_11', 'L''Archivista delle Risate', 'Individua quale giocatore ha la risata più riconoscibile e imitala immediatamente dopo che ha riso senza fargli capire che era un''imitazione.', ARRAY['house_party','bar'], 'osservazione', 'media', 150, 10, 2, 'peer_witness', ARRAY[]::text[], true),
('house_12', 'Il Complice Silenzioso (Coop)', 'Assieme al partner, ogni volta che un terzo giocatore parla, annuite sincronizzati in silenzio per 3 volte nell''arco di 10 minuti.', ARRAY['house_party'], 'collaborazione', 'media', 190, 12, 3, 'peer_witness', ARRAY[]::text[], true),
('house_13', 'Il Gossip Filosofico', 'Trasforma una banale chiacchiera di gossip su conoscenti in una profonda dissertazione esistenziale sul destino dell''umanità.', ARRAY['house_party','bar'], 'creativita', 'difficile', 210, 10, 2, 'peer_witness', ARRAY[]::text[], true),
('house_14', 'La Prova del Cuoco Spacciata', 'Fai credere che uno snack industriale confezionato sia una ricetta segreta preparata a mano da tua nonna.', ARRAY['house_party'], 'bluff', 'difficile', 260, 10, 2, 'peer_target', ARRAY[]::text[], true),
('house_15', 'L''Ordine Cronologico', 'Fai elencare a un amico tutti i cellulari che ha posseduto nella sua vita in ordine cronologico esatto.', ARRAY['house_party','bar'], 'deduzione', 'facile', 110, 8, 2, 'peer_target', ARRAY[]::text[], true),
('house_16', 'Il Saluto Segreto Improvvisato', 'Insegna a un amico una stretta di mano segreta con 4 passaggi bizzarri e usatela come saluto ufficiale per il resto della serata.', ARRAY['house_party','outdoor'], 'socializzazione', 'media', 150, 8, 2, 'peer_target', ARRAY[]::text[], true),
('house_17', 'La Sfida del Pollice', 'Appoggia il pollice sul bordo del tavolo. Tutti quelli che lo vedono devono fare lo stesso. L''ultimo a farlo perde (e tu incassi i punti se lo notano in 3).', ARRAY['house_party','bar'], 'chaos', 'media', 160, 5, 4, 'group_vote', ARRAY[]::text[], true),
('house_18', 'L''Albero Genealogico dei Debiti', 'Ricorda a un amico un piccolo debito morale o materiale insignificante di almeno 2 anni fa (es. "un pacchetto di gomme nel 2022") con assoluta precisione scenica.', ARRAY['house_party','bar'], 'deduzione', 'facile', 90, 6, 2, 'peer_target', ARRAY[]::text[], true),
('house_19', 'La Telecronaca Sotto Voce', 'Fai la telecronaca a bassa voce di ciò che sta facendo un amico in cucina come se fosse la finale di Champions League.', ARRAY['house_party'], 'creativita', 'difficile', 220, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('house_20', 'Il Master del Salotto (Leggendaria)', 'Riesci a far spostare l''intera conversazione del salotto su un argomento a tua scelta deciso prima, e mantenerla viva per almeno 12 minuti continuativi.', ARRAY['house_party'], 'persuasione', 'leggendaria', 400, 15, 4, 'group_vote', ARRAY[]::text[], true),
('out_01', 'Il Navigatore Cieco', 'Guida il gruppo verso una direzione o una via laterale sostenendo con assoluta sicurezza che "da qui si accorcia", anche se allunghi la strada.', ARRAY['outdoor'], 'persuasione', 'media', 160, 12, 3, 'peer_witness', ARRAY[]::text[], true),
