('out_13', 'La Brezza Improvvisa', 'Lamentati credibilmente del vento o della temperatura esattamente prima che un altro compagno dica spontaneamente la stessa cosa.', ARRAY['outdoor'], 'osservazione', 'media', 130, 10, 2, 'peer_witness', ARRAY[]::text[], true),
('out_14', 'Il Girotondo Inconsapevole', 'Guida il gruppo attorno a un monumento o un''aiuola facendo compiere un cerchio completo a 360 gradi prima di riprendere la rotta.', ARRAY['outdoor'], 'chaos', 'difficile', 270, 8, 3, 'peer_witness', ARRAY[]::text[], true),
