('out_20', 'La Spedizione Notturna (Leggendaria)', 'Porta l''intero gruppo a scoprire un angolo o vicolo del quartiere in cui nessuno dei presenti era mai stato prima.', ARRAY['outdoor'], 'socializzazione', 'leggendaria', 390, 20, 4, 'group_vote', ARRAY[]::text[], true),
('chaos_01', 'Il Sabotatore di Brindisi', 'Durante il prossimo brindisi, tocca i bicchieri di tutti tranne uno specifico giocatore, scusandoti subito dopo dicendo "Ops, non ti avevo visto!".', ARRAY['chaos','bar','house_party'], 'chaos', 'facile', 110, 5, 2, 'peer_witness', ARRAY[]::text[], true),
('chaos_02', 'L''Inversione di Ruoli', 'Imita il tic verbale o la posa abituale di un tuo amico per 5 minuti finché un terzo giocatore non dice "Perché ti muovi/parli come lui?".', ARRAY['chaos','house_party','bar'], 'bluff', 'difficile', 260, 10, 3, 'peer_witness', ARRAY[]::text[], true),
('chaos_03', 'Il Tradimento dell''Alleanza (Coop)', 'Fingi un''alleanza segreta con un giocatore per completare un obiettivo, ma fai convalidare l''obiettivo da un testimone diverso prima di lui.', ARRAY['chaos'], 'bluff', 'difficile', 280, 15, 3, 'peer_witness', ARRAY[]::text[], true),
('chaos_04', 'La Notifica Fantasma', 'Guarda lo schermo del telefono con espressione di autentico shock o stupore, coprilo con la mano e rifiutati di dire cosa hai visto a chiunque te lo chieda per 3 minuti.', ARRAY['chaos','bar','house_party','outdoor'], 'bluff', 'facile', 120, 6, 2, 'peer_witness', ARRAY[]::text[], true),
