('chaos_08', 'Il Furto del Bicchiere Fantasma', 'Scambia il tuo bicchiere (se dello stesso tipo e contenuto sicuro) con quello di un compagno distratto senza che se ne accorga.', ARRAY['chaos','house_party','bar'], 'chaos', 'difficile', 240, 8, 2, 'peer_witness', ARRAY[]::text[], true),
